BEGIN;

-- Add assignments without copying or assigning any existing members.
CREATE TABLE "member_role" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "member_id" INTEGER NOT NULL,
    "role_code" TEXT NOT NULL,
    "starts_on" DATE,
    "ends_on" DATE,
    "assigned_by" INTEGER,
    "notes" VARCHAR(500),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "member_role_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "member_role_dates_check" CHECK ("ends_on" IS NULL OR "starts_on" IS NULL OR "ends_on" >= "starts_on"),
    CONSTRAINT "member_role_member_id_fkey" FOREIGN KEY ("member_id") REFERENCES "member"("member_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "member_role_role_code_fkey" FOREIGN KEY ("role_code") REFERENCES "role"("role_code") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "member_role_assigned_by_fkey" FOREIGN KEY ("assigned_by") REFERENCES "member"("member_id") ON DELETE RESTRICT ON UPDATE NO ACTION
);

-- One open assignment per member/role; ended history may repeat.
CREATE UNIQUE INDEX "uq_member_role_active" ON "member_role"("member_id", "role_code") WHERE "ends_on" IS NULL;
-- Lookup of open assignments by role follows the approved reference design.
CREATE INDEX "idx_member_role_role_active" ON "member_role"("role_code") WHERE "ends_on" IS NULL;

COMMIT;
